RESOURCE_USAGE = {
    'raw_materials': {'A': 2, 'B': 1, 'C': 3},
    'production_time': {'A': 1, 'B': 2, 'C': 2}
}
RESOURCE_LIMITS = {
    'raw_materials': 10,
    'production_time': 8
}

# Create problem instance
prob = pulp.LpProblem(PROBLEM_NAME, pulp.LpMaximize)

# Define integer decision variables
PRODUCTS = list(PROFIT_RATES.keys())
variables = {p: pulp.LpVariable(p, lowBound=0, cat='Integer') for p in PRODUCTS}

# Objective function: maximize total profit
prob += sum(PROFIT_RATES[p] * variables[p] for p in PRODUCTS)

# Resource constraints
for resource, limits in RESOURCE_LIMITS.items():
    prob += sum(RESOURCE_USAGE[resource][p] * variables[p] for p in PRODUCTS) <= limits

# Solve using CBC solver
prob.solve(pulp.PULP_CBC_CMD(msg=0))

# Output results
print(f"Optimal profit: {pulp.value(prob.objective)}")

